input.sparql:
PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT ?s ?name ?ts WHERE {
  ?s a brick:AirHandlingUnit ; rdfs:label "AHU03" .
  ?s brick:hasPoint ?p .
  ?p a brick:ElectricPowerConsumption .
  ?p ref:hasTimeseriesId ?ts .
  OPTIONAL { ?p rdfs:label ?name }
}

SELECT ?s ?p ?cls ?ts WHERE {
  ?s rdfs:label "AHU03" .
  ?s brick:hasPoint ?p .
  OPTIONAL { ?p rdf:type ?cls }
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
} LIMIT 200

SELECT ?p ?cls ?ts WHERE {
  ?p rdfs:label ?lbl .
  FILTER (regex(str(?lbl), "AHU03", "i") && regex(str(?cls), "Electric", "i"))
  OPTIONAL { ?p rdf:type ?cls }
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
} LIMIT 50

SELECT ?p ?cls ?ts WHERE {
  ?p rdf:type ?cls .
  FILTER (regex(str(?cls), "Electric", "i"))
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
} LIMIT 100
